  "Process and workflow": ["arrow-down","arrow-left","arrow-right","arrow-u-up-left","arrow-up","arrows-clockwise","arrows-left-right","calendar","calendar-check","calendar-x","clock","clock-countdown","flow-arrow","funnel","gear","gear-six","git-branch","hourglass","pause","play","repeat","stop","timer","toolbox","tree-structure","wrench"],
  "General": ["asterisk","caret-down","caret-right","circles-three","cube","dot","dots-three","flag","flag-banner","hand-pointing","info","lightbulb","lightning","minus","plus","push-pin","puzzle-piece","question","squares-four","stack","strategy","tag"],
  "Safety and risk": ["bandaids","biohazard","eye","eye-slash","fire","fire-extinguisher","first-aid","first-aid-kit","hard-hat","heartbeat","lifebuoy","prohibit","prohibit-inset","pulse","radioactive","shield","shield-check","shield-slash","shield-warning","siren","skull","warning","warning-circle","warning-diamond","warning-octagon"],
  "Communication": ["bell","bell-ringing","broadcast","chat-circle","chat-text","chats","envelope","envelope-open","link","megaphone","phone","phone-call","radio","share-network","wifi-high"],
  "Compliance and documents": ["book","book-bookmark","book-open","bookmark","certificate","check","check-circle","check-square","checks","clipboard","clipboard-text","file-magnifying-glass","file-plus","file-text","file-x","files","folder","folder-open","gavel","list-bullets","list-checks","list-numbers","note","note-pencil","notepad","read-cv-logo","scales","seal-check","seal-warning","signature","stamp","x-circle"],
  "People and roles": ["briefcase","chalkboard-teacher","handshake","headset","identification-badge","identification-card","person","person-simple-walk","student","user","user-circle","user-circle-check","user-focus","user-gear","users","users-three","wheelchair"],
